INSERT INTO tassonomia_versione (id, codice, versione_documento, data_acquisizione, fonte_url,
INSERT INTO tassonomia_voce (id, versione_id, padre_id, livello, codice, slug_misp, nome, descrizione, sezione, ordine)
VALUES
(1, 1, NULL, 'MACROCATEGORIA', 'BC', NULL, 'Baseline Characterization', NULL, '3.1', 1),
(2, 1, NULL, 'MACROCATEGORIA', 'TT', NULL, 'Threat Type', NULL, '3.2', 2),
(3, 1, NULL, 'MACROCATEGORIA', 'TA', NULL, 'Threat Actor', NULL, '3.3', 3),
(4, 1, NULL, 'MACROCATEGORIA', 'AC', NULL, 'Additional Context', NULL, '3.4', 4),
(5, 1, 1, 'PREDICATO', 'BC:IM', 'impact', 'Impact', NULL, '3.1.1', 1),
(6, 1, 5, 'VALORE', 'BC:IM_AC', 'account-compromise', 'Account Compromise', 'Cyber events that have resulted in the compromise of a user account or a service account. It is possible to specify the type of compromised account using the predicate Involved asset.', '3.1.1.1', 1),
(7, 1, 5, 'VALORE', 'BC:IM_AP', 'application-compromise', 'Application Compromise', 'Cyber events that have resulted in the compromise of an application or service, including web applications, mobile applications, databases, etc. It is possible to specify the type of application compromise using the predicate Involved asset.', '3.1.1.2', 2),
(8, 1, 5, 'VALORE', 'BC:IM_AV', 'availability', 'Availability', 'Cyber events in which malicious activities conducted by an attacker have affected the availability of the system or service provided. The predicate Availability must also be explicitly stated.', '3.1.1.3', 3),
(9, 1, 5, 'VALORE', 'BC:IM_DX', 'data-exfiltration', 'Data Exfiltration', 'Cyber events in which the confidentiality of information present on an IT asset has been compromised. This loss or leak of data can occur due to malicious activities or accidentally.', '3.1.1.4', 4),
(10, 1, 5, 'VALORE', 'BC:IM_DE', 'data-exposure', 'Data Exposure', 'Unauthorized disclosure of sensitive or confidential data, caused by security vulnerabilities, configuration errors, or inadequate information management practices.', '3.1.1.5', 5),
(11, 1, 5, 'VALORE', 'BC:IM_DM', 'data-manipulation', 'Data Manipulation', 'Cyber events in which the integrity of information present on an IT asset has been compromised. This value includes the modification or destruction of data by a malicious actor.', '3.1.1.6', 6),
(12, 1, 5, 'VALORE', 'BC:IM_NO', 'no-impact', 'No Impact', 'A cyber event that could have compromised the availability, integrity or confidentiality of data or services, but was effectively prevented or did not occur.', '3.1.1.7', 7),
(13, 1, 5, 'VALORE', 'BC:IM_SY', 'system-compromise', 'System Compromise', 'Cyber events that have resulted in the compromise of an IT asset, for example, by altering its integrity.', '3.1.1.8', 8),
(14, 1, 5, 'VALORE', 'BC:IM_OT', 'other', 'Other', 'Cyber events related to Impact that are not identifiable with the other values defined in the subset.', '3.1.1.9', 9),
(15, 1, 1, 'PREDICATO', 'BC:RO', 'root-cause', 'Root Cause', NULL, '3.1.2', 2),
(16, 1, 15, 'VALORE', 'BC:RO_HU', 'human-errors', 'Human Errors', 'Events caused by an unintentional human mistake. An example is an incorrect operation that affects the intended functionality of an IT asset.', '3.1.2.1', 1),
(17, 1, 15, 'VALORE', 'BC:RO_MA', 'malicious-actions', 'Malicious Actions', 'Any attempt to compromise the integrity, confidentiality, or availability of an IT asset.', '3.1.2.2', 2),
(18, 1, 15, 'VALORE', 'BC:RO_NA', 'natural-phenomena', 'Natural Phenomena', 'Events caused by a natural occurrence, such as earthquakes, avalanches, and floods.', '3.1.2.3', 3),
(19, 1, 15, 'VALORE', 'BC:RO_SY', 'system-failure', 'System Failure', 'An unforeseen event in which a system ceases to function according to its intended design specifications, resulting in a loss of service or a significant reduction in the quality of the service provided.', '3.1.2.4', 4),
(20, 1, 15, 'VALORE', 'BC:RO_TH', 'third-party-failure', 'Third Party Failure', 'Interruption or degradation of the performance of a primary system attributable to malfunctions or failures of services provided by third parties.', '3.1.2.5', 5),
(21, 1, 1, 'PREDICATO', 'BC:SE', 'severity', 'Severity', NULL, '3.1.3', 3),
(22, 1, 21, 'VALORE', 'BC:SE_HI', 'high', 'High', 'The organization is no longer able to provide essential services to users; or personal or proprietary data/information has been modified, deleted, or exfiltrated; or recovery from the incident is not possible.', '3.1.3.1', 1),
(23, 1, 21, 'VALORE', 'BC:SE_ME', 'medium', 'Medium', 'The organization is able to provide an essential service only to a portion of its users; or access to and exfiltration of personal or proprietary data/information has been detected; or recovery is possible, but the timeframe is unknown.', '3.1.3.2', 2),
(24, 1, 21, 'VALORE', 'BC:SE_LO', 'low', 'Low', 'The organization can still provide essential services to all users, but they are not optimal in terms of efficiency; or access to sensitive or proprietary data/information has been detected; or recovery is possible within a known timeframe, even with additional resources.', '3.1.3.3', 3),
(25, 1, 21, 'VALORE', 'BC:SE_NO', 'none', 'None', 'No effect on the organization''s ability to provide services to users; or no information has been subject to unauthorized access, exfiltration, modification, or deletion; or the time required for recovery is predictable with existing resources.', '3.1.3.4', 4),
(26, 1, 1, 'PREDICATO', 'BC:VG', 'victim-geography', 'Victim Geography', NULL, '3.1.4', 4),
(27, 1, 26, 'VALORE', 'BC:VG_IT', 'italy', 'Italy', 'The cyber event has impacted IT assets located within Italy.', '3.1.4.1', 1),
(28, 1, 26, 'VALORE', 'BC:VG_AF', 'africa', 'Africa', 'The cyber event has impacted IT assets geographically located in the African continent', '3.1.4.2', 2),
(29, 1, 26, 'VALORE', 'BC:VG_AM', 'america', 'America', 'The cyber event has impacted IT assets geographically located in the American continent.', '3.1.4.3', 3),
(30, 1, 26, 'VALORE', 'BC:VG_AN', 'antarctica', 'Antarctica', 'The cyber event has impacted IT assets geographically located in the Antarctic continent.', '3.1.4.4', 4),
(31, 1, 26, 'VALORE', 'BC:VG_AS', 'asia', 'Asia', 'The cyber event has impacted IT assets geographically located in the Asian continent.', '3.1.4.5', 5),
(32, 1, 26, 'VALORE', 'BC:VG_EU', 'europe', 'Europe', 'The cyber event has impacted IT assets geographically located in the European continent.', '3.1.4.6', 6),
(33, 1, 26, 'VALORE', 'BC:VG_OC', 'oceania', 'Oceania', 'The cyber event has impacted IT assets located within the Oceanic continent.', '3.1.4.7', 7),
(34, 1, 26, 'VALORE', 'BC:VG_GL', 'global', 'Global', 'The cyber event has impacted IT assets distributed across multiple countries or that it has a potentially global impact.', '3.1.4.8', 8),
(35, 1, 2, 'PREDICATO', 'TT:AC', 'active-scanning', 'Active Scanning', NULL, '3.2.1', 1),
(36, 1, 35, 'VALORE', 'TT:AC_CR', 'credential-scanning', 'Credential Scanning', 'Cyber events in which a malicious actor performs an active scan to detect weak or improperly configured authentication credentials, or credentials exposed on an IT asset.', '3.2.1.1', 1),
(37, 1, 35, 'VALORE', 'TT:AC_NE', 'network-scanning', 'Network Scanning', 'Cyber events in which a malicious actor uses techniques and procedures aimed at identifying the presence of services running on remote IT assets or on assets connected to the target infrastructure.', '3.2.1.2', 2),
(38, 1, 35, 'VALORE', 'TT:AC_VU', 'vulnerability-scanning', 'Vulnerability Scanning', 'Cyber events in which a malicious actor uses techniques and procedures specifically aimed at identifying vulnerabilities present in an IT asset in order to map the attack surface.', '3.2.1.3', 3),
(39, 1, 35, 'VALORE', 'TT:AC_OT', 'other', 'Other', 'Cyber events related to Active scanning that are not identifiable with the other values defined in the subset.', '3.2.1.4', 4),
(40, 1, 2, 'PREDICATO', 'TT:AV', 'availability', 'Availability', NULL, '3.2.2', 2),
(41, 1, 40, 'VALORE', 'TT:AV_DA', 'data-encryption', 'Data Encryption', 'Cyber events in which a malicious actor applies encryption algorithms to data in a compromised computer system without the owner''s consent, in order to render it inaccessible.', '3.2.2.1', 1),
(42, 1, 40, 'VALORE', 'TT:AV_DD', 'ddos', 'DDoS', 'Cyber events in which a malicious actor launches an attack from multiple, distributed sources, with the aim of compromising the availability of a computing asset or service by exhausting its network, processing, or memory resources.', '3.2.2.2', 2),
(43, 1, 40, 'VALORE', 'TT:AV_DO', 'dos', 'DoS', 'Cyber events in which a malicious actor launches an attack aimed at compromising the availability of a computing asset or service by exhausting its network, processing, or memory resources.', '3.2.2.3', 3),
(44, 1, 40, 'VALORE', 'TT:AV_MI', 'misconfiguration', 'Misconfiguration', 'Non-malicious cyber events in which an incorrect or suboptimal configuration of a computer asset or its component has compromised the availability of a service. ', '3.2.2.4', 4),
(45, 1, 40, 'VALORE', 'TT:AV_OU', 'outage', 'Outage', 'Non-malicious cyber events in which a total or partial loss of availability of a computer asset has been observed due to natural or human-caused events. ', '3.2.2.5', 5),
(46, 1, 40, 'VALORE', 'TT:AV_OT', 'other', 'Other', 'Cyber events in which a loss of availability of a computer asset or application is encountered due to a cause that does not fall within those indicated in the other values associated with the Availability predicate.', '3.2.2.6', 6),
(47, 1, 2, 'PREDICATO', 'TT:BA', 'brand-abuse', 'Brand Abuse', NULL, '3.2.3', 3),
(48, 1, 47, 'VALORE', 'TT:BA_AI', 'account-impersonation', 'Account Impersonation', 'The activity in which a malicious actor impersonates another person, system, or organization in order to deceive the victim and gain unauthorized access to sensitive information.', '3.2.3.1', 1),
(49, 1, 47, 'VALORE', 'TT:BA_CS', 'cybersquatting', 'Cybersquatting', 'Registering and abusively using an Internet domain name that is identical or similar to registered trademarks, service names, personal or corporate names, with the malicious intent of diverting traffic to other sites.', '3.2.3.2', 2),
(50, 1, 47, 'VALORE', 'TT:BA_NI', 'name-logo-impersonation', 'Name Logo Impersonation', 'Deliberate act of fraudulently replicating or imitating the name/logo of a recognized entity, such as a reputable organization or well-known service, with the intent to deceive the victim.', '3.2.3.3', 3),
(51, 1, 47, 'VALORE', 'TT:BA_TS', 'typosquatting', 'Typosquatting', 'When a malicious actor deliberately registers domain names which mimic existing websites with slight spelling variations, exploiting typing errors.', '3.2.3.4', 4),
(52, 1, 47, 'VALORE', 'TT:BA_OT', 'other', 'Other', 'Cyber events pertaining to Brand abuse that are not identifiable with the other values defined within the subset.', '3.2.3.5', 5),
(53, 1, 2, 'PREDICATO', 'TT:FR', 'fraud', 'Fraud', NULL, '3.2.4', 4),
(54, 1, 53, 'VALORE', 'TT:FR_BR', 'brand-abuse', 'Brand Abuse', 'Fraudulent activity in which a malicious actor exploits the notoriety of an organization to create fake websites, false advertising campaigns, or false partnerships with the purpose of damaging its reputation or conducting cybercrime activities.', '3.2.4.1', 1),
(55, 1, 53, 'VALORE', 'TT:FR_EX', 'extortion', 'Extortion', 'A criminal activity in which an attacker exerts coercion on an individual or organization to obtain financial benefits or other forms of compensation. This conduct is carried out through the threat of causing damage or disclosing sensitive information.', '3.2.4.2', 2),
(56, 1, 53, 'VALORE', 'TT:FR_MA', 'masquerade', 'Masquerade', 'A fraudulent activity in which a malicious actor assumes the identity of another user, device, or entity within a network or computer system in order to circumvent security mechanisms and gain unauthorized access to resources or computer assets.', '3.2.4.3', 3),
(57, 1, 53, 'VALORE', 'TT:FR_RE', 'resource-misuse', 'Resource Misuse', 'Cyber events in which a malicious actor has exploited the resources of a computer or network in an unauthorized manner for illicit purposes.', '3.2.4.4', 4),
(58, 1, 53, 'VALORE', 'TT:FR_SP', 'spam', 'Spam', 'Cyber events in which a malicious actor sends unsolicited or unwanted advertising messages, generally of a commercial nature.', '3.2.4.5', 5),
(59, 1, 53, 'VALORE', 'TT:FR_OT', 'other', 'Other', 'Cyber events pertaining to the Fraud predicate that are not identifiable with the other values defined within the subset.', '3.2.4.6', 6),
(60, 1, 2, 'PREDICATO', 'TT:DE', 'data-exposure', 'Data Exposure', NULL, '3.2.5', 5),
(61, 1, 60, 'VALORE', 'TT:DE_AU', 'authentication-data', 'Authentication Data', 'Cyber events in which a security breach of data pertaining to the authentication of users of the impacted information asset, such as usernames and passwords, has been identified.', '3.2.5.1', 1),
(62, 1, 60, 'VALORE', 'TT:DE_BU', 'business-data', 'Business Data', 'Cyber events in which a security breach of data pertaining to the company, such as data on its activities, its contracts, intellectual property, etc., has been identified.', '3.2.5.2', 2),
(63, 1, 60, 'VALORE', 'TT:DE_FI', 'financial-data', 'Financial Data', 'Cyber events in which a security breach of data pertaining to the company''s financial sphere, such as income, expenses, financial transaction data, etc., has been identified.', '3.2.5.3', 3),
(64, 1, 60, 'VALORE', 'TT:DE_PD', 'personal-data', 'Personal Data', 'Cyber events in which a security breach of personal data has occurred, that is, information that directly or indirectly identifies or makes identifiable a physical person.', '3.2.5.4', 4),
(65, 1, 60, 'VALORE', 'TT:DE_OT', 'other', 'Other', 'Cyber events related to Information disclosure that are not identifiable by the other values defined in the subset.', '3.2.5.5', 5),
(66, 1, 2, 'PREDICATO', 'TT:IG', 'information-gathering', 'Information Gathering', NULL, '3.2.6', 6),
(67, 1, 66, 'VALORE', 'TT:IG_AC', 'active-scanning', 'Active Scanning', 'Cyber events in which a malicious actor attempts to gather information through an active scan, that is, through direct contact with the target information asset.', '3.2.6.1', 1),
(68, 1, 66, 'VALORE', 'TT:IG_SN', 'sniffing', 'Sniffing', 'Cyber events in which an unauthorized actor uses techniques or tools to capture network packets for the purpose of stealing data, monitoring network activity, and gathering information.', '3.2.6.2', 2),
(69, 1, 66, 'VALORE', 'TT:IG_SO', 'social-engineering', 'Social Engineering', 'Cyber events in which a malicious actor uses a set of techniques and tactics to persuade an individual to perform certain actions for various purposes.', '3.2.6.3', 3),
(70, 1, 66, 'VALORE', 'TT:IG_OT', 'other', 'Other', 'Cyber events related to Information gathering that are not identifiable by the other values defined in the subset.', '3.2.6.4', 4),
(71, 1, 2, 'PREDICATO', 'TT:MA', 'malicious-code', 'Malicious Code', NULL, '3.2.7', 7),
(72, 1, 71, 'VALORE', 'TT:MA_BA', 'backdoor', 'Backdoor', 'A type of malware that grants secondary access to a compromised information asset, allowing the attacker to access it remotely and perform arbitrary actions.', '3.2.7.1', 1),
(73, 1, 71, 'VALORE', 'TT:MA_BK', 'banker', 'Banker', 'A type of malware that attempts to illicitly steal the credentials of bank clients or gain access to their financial information.', '3.2.7.2', 2),
(74, 1, 71, 'VALORE', 'TT:MA_BO', 'bot', 'Bot', 'A computer program designed to fulfill a specific purpose, whether legitimate or malicious. In the latter case, it is referred to as bot malware, which are used to create a network of zombie computers, known as a botnet.', '3.2.7.3', 3),
(75, 1, 71, 'VALORE', 'TT:MA_CO', 'coin-miner', 'Coin Miner', 'A type of malware that exploits the computing power of the target information asset to mine cryptocurrencies without the user''s knowledge.', '3.2.7.4', 4),
(76, 1, 71, 'VALORE', 'TT:MA_EX', 'exploit-kit', 'Exploit Kit', 'A collection of software tools designed to exploit vulnerabilities present in a network, a system, or an application. ', '3.2.7.5', 5),
(77, 1, 71, 'VALORE', 'TT:MA_HA', 'hacking-tool', 'Hacking Tool', 'A program designed to breach the security measures of an information asset. It is used both for legitimate activities and in unauthorized contexts or for illicit purposes.', '3.2.7.6', 6),
(78, 1, 71, 'VALORE', 'TT:MA_IN', 'information-stealer', 'Information Stealer', 'A type of malware that aims to collect information about an information asset illegitimately. Malware known as keyloggers or spyware falls into this classification.', '3.2.7.7', 7),
(79, 1, 71, 'VALORE', 'TT:MA_LO', 'loader', 'Loader', 'A type of malware that allows for the downloading and execution of additional malware on the compromised information asset. Malware known as droppers and downloaders fall into this classification.', '3.2.7.8', 8),
(80, 1, 71, 'VALORE', 'TT:MA_PO', 'potentially-unwanted-program', 'Potentially Unwanted Program', 'Software that is unwanted according to the user''s preferences. Although this classification does not indicate the presence of malware, they can pose a threat to the privacy and security of the system and the user.', '3.2.7.9', 9),
(81, 1, 71, 'VALORE', 'TT:MA_RA', 'ransomware', 'Ransomware', 'A type of threat that aims to encrypt the data of the target information asset in order to compromise its availability and integrity.', '3.2.7.10', 10),
(82, 1, 71, 'VALORE', 'TT:MA_RE', 'remote-access-tool', 'Remote Access Tool', 'A type of malware that allows an attacker to control a target information asset remotely. It allows for the execution of various unauthorized actions, such as data acquisition, file transfer, and the execution of arbitrary commands.', '3.2.7.11', 11),
(83, 1, 71, 'VALORE', 'TT:MA_RO', 'rootkit', 'Rootkit', 'A typically sophisticated type of malware designed to infiltrate an operating system or application, masking its presence and gaining elevated access privileges.', '3.2.7.12', 12),
(84, 1, 71, 'VALORE', 'TT:MA_TR', 'trojan', 'Trojan', 'A type of software that presents itself to the user in the form of a legitimate or otherwise harmless program, but which, once executed, aims to download and launch further malicious software on the target information asset. ', '3.2.7.13', 13),
(85, 1, 71, 'VALORE', 'TT:MA_VI', 'virus', 'Virus', 'A potentially harmful software that, when executed on an information asset, aims to self-replicate by modifying the running programs and altering their operations.', '3.2.7.14', 14),
(86, 1, 71, 'VALORE', 'TT:MA_WE', 'webshell', 'Webshell', 'A type of script or program that is installed on a compromised web server in order to gain unauthorized and persistent access to the information asset.', '3.2.7.15', 15),
(87, 1, 71, 'VALORE', 'TT:MA_WI', 'wiper', 'Wiper', 'A type of malware whose primary objective is to irreversibly delete data and files present on a compromised information asset.', '3.2.7.16', 16),
(88, 1, 71, 'VALORE', 'TT:MA_WO', 'worm', 'Worm', 'A potentially harmful software that an attacker can exploit to replicate malware within an information asset in order to compromise its functionality.', '3.2.7.17', 17),
(89, 1, 71, 'VALORE', 'TT:MA_UN', 'unknown', 'Unknown', 'A type of malicious code for which there is insufficient information to indicate its nature. The execution of malicious code or malware has been detected, but its type cannot yet be determined.', '3.2.7.18', 18),
(90, 1, 2, 'PREDICATO', 'TT:SO', 'social-engineering', 'Social Engineering', NULL, '3.2.8', 8),
(91, 1, 90, 'VALORE', 'TT:SO_BA', 'baiting', 'Baiting', 'Fraudulent activities in which a malicious actor attracts the victim by means of a lure, such as the promise of receiving a benefit or obtaining an advantage. ', '3.2.8.1', 1),
(92, 1, 90, 'VALORE', 'TT:SO_PH', 'phishing', 'Phishing', 'Cyber events in which a user is contacted, via email or other messaging tools, by a malicious actor with the aim of leading the victim to execute malicious code or visit fabricated resources.', '3.2.8.2', 2),
(93, 1, 90, 'VALORE', 'TT:SO_SM', 'smishing', 'Smishing', 'Cyber events in which a user is contacted, via the sending of short text messages, SMS, by a malicious actor with the aim of leading the victim to execute malicious code or to visit fabricated resources.', '3.2.8.3', 3),
(94, 1, 90, 'VALORE', 'TT:SO_SP', 'spear-phishing', 'Spear Phishing', 'A type of phishing targeting subjects of specific interest, involving the sending of a highly personalized message from an email account that appears familiar to the victim, with the intent of stealing sensitive information or inducing them to open/download malicious attachments or links.', '3.2.8.4', 4),
(95, 1, 90, 'VALORE', 'TT:SO_VI', 'vishing', 'Vishing', 'Cyber events in which a user is contacted, via voice communication systems, by a criminal actor with the aim of leading the victim to execute malicious code or to steal data.', '3.2.8.5', 5),
(96, 1, 90, 'VALORE', 'TT:SO_WA', 'watering-hole', 'Watering Hole', 'Cyber events in which an attacker aims to compromise a specific group of users by infecting websites that are known to be regularly visited by that group.', '3.2.8.6', 6),
(97, 1, 90, 'VALORE', 'TT:SO_OT', 'other', 'Other', 'Cyber events related to Social engineering that are not identifiable with the other values defined in the subset.', '3.2.8.7', 7),
(98, 1, 2, 'PREDICATO', 'TT:VU', 'vulnerability', 'Vulnerability', NULL, '3.2.9', 9),
(99, 1, 98, 'VALORE', 'TT:VU_0-', '0-day-vulnerability', '0-Day Vulnerability', 'A vulnerability that is not publicly known, and therefore could be exploited by an attacker to compromise an information system and undermine its integrity, confidentiality, and availability.', '3.2.9.1', 1),
(100, 1, 98, 'VALORE', 'TT:VU_N-', 'n-day-vulnerability', 'n-Day Vulnerability', 'A 0-day vulnerability that has been made public for more than one day, regardless of the release of corrective software.', '3.2.9.2', 2),
(101, 1, 98, 'VALORE', 'TT:VU_SE', 'security-misconfiguration', 'Security Misconfiguration', 'The incorrect configuration of an information asset which can lead to security risks and cause flaws that can be easily exploited by a cybercriminal to compromise a system.', '3.2.9.3', 3),
(102, 1, 98, 'VALORE', 'TT:VU_UN', 'unwanted-exposed-services', 'Unwanted Exposed Services', 'The information asset involved in the security event exposes network services that are generally not recommended because they can expand the attack surface and can impact the security posture.', '3.2.9.4', 4),
(103, 1, 98, 'VALORE', 'TT:VU_WE', 'weak-cryptography', 'Weak Cryptography', 'Cyber events related to the improper or incorrect use of security mechanisms related to encryption.', '3.2.9.5', 5),
(104, 1, 98, 'VALORE', 'TT:VU_PC', 'proof-of-concept', 'Proof Of Concept', 'The availability of a technical demonstration created to validate the presence of a theoretical vulnerability, demonstrating how it can be exploited in a software or computer system.', '3.2.9.6', 6),
(105, 1, 98, 'VALORE', 'TT:VU_OT', 'other', 'Other', 'Cyber events related to Vulnerability that are not identifiable with the other values defined in the subset.', '3.2.9.7', 7),
(106, 1, 3, 'PREDICATO', 'TA:AM', 'adversary-motivation', 'Adversary Motivation', NULL, '3.3.1', 1),
(107, 1, 106, 'VALORE', 'TA:AM_DE', 'destruction', 'Destruction', 'Cyber events in which an attacker has conducted malicious or illicit activities aimed at damaging an information asset in order to compromise its operation, interrupt the total or partial provision of services, or prevent authorized personnel from accessing it.', '3.3.1.1', 1),
(108, 1, 106, 'VALORE', 'TA:AM_ES', 'espionage', 'Espionage', 'Cyber events in which an attacker has conducted an unlawful activity aimed at acquiring sensitive, proprietary, or classified data/information in order to achieve economic gain, competitive advantage, or for political reasons. ', '3.3.1.2', 2),
(109, 1, 106, 'VALORE', 'TA:AM_ID', 'ideology', 'Ideology', 'Cyber events in which an attacker has conducted malicious or illicit activities to spread a message of an ideological nature to the affected organization, the users of the impacted service, or any third party.', '3.3.1.3', 3),
(110, 1, 106, 'VALORE', 'TA:AM_IN', 'influence-and-disinformation', 'Influence And Disinformation', 'Cyber events in which there is an intentional dissemination of inaccurate or distorted news or information in order to influence the actions and choices of someone.', '3.3.1.4', 4),
(111, 1, 106, 'VALORE', 'TA:AM_PR', 'profit', 'Profit', 'Cyber events in which an attacker or group carries out malicious or illicit actions in order to obtain, directly or indirectly, a profit.', '3.3.1.5', 5),
(112, 1, 106, 'VALORE', 'TA:AM_OT', 'other', 'Other', 'Cyber events related to Adversary motivation that are not identifiable with the other values defined in the subset.', '3.3.1.6', 6),
(113, 1, 3, 'PREDICATO', 'TA:AD', 'adversary-type', 'Adversary Type', NULL, '3.3.2', 2),
(114, 1, 113, 'VALORE', 'TA:AD_CR', 'criminal', 'Criminal', 'Cyber events in which the attacker or group that caused the event can be categorized into the more generic type of "criminal" whose goals tend to generate profit from the actions carried out.', '3.3.2.1', 1),
(115, 1, 113, 'VALORE', 'TA:AD_HA', 'hacktivist', 'Hacktivist', 'Cyber events in which the subversive use of digital tools is employed to promote a political agenda or principles of social connotation.', '3.3.2.2', 2),
(116, 1, 113, 'VALORE', 'TA:AD_IN', 'insider', 'Insider', 'Cyber events in which an attacker uses their permissions or the knowledge acquired during routine work activities to carry out a cyberattack from within the network they operate.', '3.3.2.3', 3),
(117, 1, 113, 'VALORE', 'TA:AD_NA', 'nation-state', 'Nation State', 'Cyber events conducted by state entities or groups, or sponsored by the state, meaning groups that conduct advanced cyber operations on behalf of a government or a sovereign state.', '3.3.2.4', 4),
(118, 1, 4, 'PREDICATO', 'AC:AB', 'abusive-content', 'Abusive Content', NULL, '3.4.1', 1),
(119, 1, 118, 'VALORE', 'AC:AB_DI', 'disturbing-content', 'Disturbing Content', 'Any type of material or information disseminated through computer systems that may be considered offensive, inappropriate, harmful, or that may cause psychological or emotional distress.', '3.4.1.1', 1),
(120, 1, 118, 'VALORE', 'AC:AB_HA', 'harmful-speech', 'Harmful Speech', 'Events involving any form of communication expressed through digital platforms that may cause harm, distress, or discrimination to individuals or groups.', '3.4.1.2', 2),
(121, 1, 118, 'VALORE', 'AC:AB_OT', 'other', 'Other', 'Cyber events related to Abusive content that are not identifiable with the other values defined in the subset.', '3.4.1.3', 3),
(122, 1, 4, 'PREDICATO', 'AC:AS', 'asset-source-geography', 'Asset Source Geography', NULL, '3.4.2', 2),
